public final static ScopedValue<String> CONTEXT = ScopedValue.newInstance();

public void execute() {
    ScopedValue.where(CONTEXT, "User-123").run(() -> {
        // Context is accessible here and in any child threads
        processRequest();
    });
}

private void processRequest() {
    System.out.println(CONTEXT.get());
}
